/** Offline-baked M70 value-noise lattice. Identical bytes on every GPU.
 * Regenerate with node scripts/qa/bake-puddle-noise.mjs. */
const encoded=''
export function createPuddleNoiseTexture(gl: WebGLRenderingContext): WebGLTexture {
  const texture=gl.createTexture()!
  const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0))
  gl.activeTexture(gl.TEXTURE0)
  gl.bindTexture(gl.TEXTURE_2D,texture)
  gl.texImage2D(gl.TEXTURE_2D,0,gl.LUMINANCE,256,256,0,gl.LUMINANCE,gl.UNSIGNED_BYTE,bytes)
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.NEAREST)
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.NEAREST)
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.REPEAT)
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.REPEAT)
  return texture
}
